1	/**
2	 * Selection escalation math (design.md D4): a non-empty selection range
3	 * that crosses a node boundary expands to the minimal contiguous cover of
4	 * whole sibling subtrees. Pure module — no CodeMirror imports; the CM6
5	 * adapter (src/plugin/transaction-filter.ts) converts to/from character
6	 * offsets and handles multi-range selections (each range escalates
7	 * independently, per D4 — that iteration lives in the adapter, not here).
8	 *
9	 * Cursors (empty ranges) are never touched by this layer — `escalateRange`/
10	 * `escalateRanges` leave them exactly as received. Cursor PLACEMENT (marker
11	 * prefixes, and — as of content-space-caret — gap lines too) is a separate,
12	 * broader mechanism: `./caret.ts`'s `resolvePlacement`, wired in at the
13	 * same `transaction-filter.ts` call site this module's escalation runs
14	 * through. Originally that mechanism was list-item-marker-only
15	 * (`clampCursorToContent`, design.md D13, node-edit-enforcement's second
16	 * manual pass, 2026-07-21); content-space-caret retired it in favor of the
17	 * general addressable-position rule, which subsumes the marker case and
18	 * extends it to gap lines (docs/research/13, "Gap-line cursor
19	 * transparency").
20	 *
21	 * `coveredSubtreeRoots` (escalated-selection-decoration, docs/research/13)
22	 * is the read-only counterpart: given a range that's already in place,
23	 * which subtree(s), if any, does it exactly cover? Built from the same
24	 * `siblingRunCover`/`subtreeCoverOf` geometry `escalateRange` uses to
25	 * escalate a range in the first place — a membership test, not new math.
26	 *
27	 * A subtree's cover (`subtreeCoverEnd`) includes its own trailing gap
28	 * in full (escalate-include-owned-gap, docs/research/13's "Escalation math
29	 * re-examination candidate"): gap ownership is already all-or-nothing in
30	 * the parse model, so once a node is escalated into a selection — via the
31	 * gap-line trigger or by a boundary crossing reaching its content — its
32	 * whole gap comes with it, not just whatever the drag happened to reach.
33	 *
34	 * `subtreeCoverOf`/`Cover` are also exported for `select-all-ladder.ts`
35	 * (progressive-select-all): the Mod-A ladder's rungs are built from the
36	 * same subtree-cover geometry, not reimplemented.
37	 */
38	
39	import type { NodePath, OutlineDoc, OutlineNode } from './model';
40	import { findPath } from './model';
41	import { nodeAtLine } from './locate';
42	
43	export interface LinePos {
44	  readonly line: number;
45	  readonly ch: number;
46	}
47	
48	/** A selection range with orientation preserved: `anchor` is the drag/
49	 * extend origin, `head` is the current end — `head` may be before or after
50	 * `anchor` in document order ("backward" vs "forward"). */
51	export interface LineRange {
52	  readonly anchor: LinePos;
53	  readonly head: LinePos;
54	}
55	
56	function isEmpty(range: LineRange): boolean {
57	  return range.anchor.line === range.head.line && range.anchor.ch === range.head.ch;
58	}
59	
60	function posBefore(a: LinePos, b: LinePos): boolean {
61	  return a.line < b.line || (a.line === b.line && a.ch < b.ch);
62	}
63	
64	function isBackward(range: LineRange): boolean {
65	  return posBefore(range.head, range.anchor);
66	}
67	
68	function posEqual(a: LinePos, b: LinePos): boolean {
69	  return a.line === b.line && a.ch === b.ch;
70	}
71	
72	export function rangesEqual(a: LineRange, b: LineRange): boolean {
73	  return posEqual(a.anchor, b.anchor) && posEqual(a.head, b.head);
74	}
75	
76	/** A node's own absolute start line (0-based) in `doc`. */
77	function startLineOf(doc: OutlineDoc, target: OutlineNode): number {
78	  let line = doc.preamble.length;
79	  let found = -1;
80	  const walk = (node: OutlineNode): void => {
81	    if (found !== -1) return;
82	    if (node === target) {
83	      found = line;
84	      return;
85	    }
86	    line += node.lines.length + node.trailingGap.length;
87	    node.children.forEach(walk);
88	  };
89	  doc.children.forEach(walk);
90	  return found;
91	}
92	
93	/** Total line count of a node's own subtree (its lines + gap, plus every
94	 * descendant's), for skipping past a preceding sibling wholesale. */
95	function subtreeLineCount(node: OutlineNode): number {
96	  let count = node.lines.length + node.trailingGap.length;
97	  for (const child of node.children) count += subtreeLineCount(child);
98	  return count;
99	}
100	
101	/**
102	 * The end position of a subtree's cover: the last line of its deepest
103	 * last-descendant, INCLUDING that leaf's own trailing gap in full
104	 * (escalate-include-owned-gap: gap ownership is all-or-nothing, so a
105	 * subtree's cover always carries its whole owned gap along, not just
106	 * whatever a drag happened to reach). `startLine` is `node`'s own absolute
107	 * start line.
108	 */
109	function subtreeCoverEnd(node: OutlineNode, startLine: number): LinePos {
110	  if (node.children.length === 0) {
111	    if (node.trailingGap.length > 0) {
112	      // Gap lines are semantically blank (parse.ts's `isBlank` treats any
113	      // whitespace-only line as blank) even though whitespace-only ones are
114	      // stored verbatim — `ch: 0` here, not the stored line's length, so
115	      // matching (`coveredSubtreeRoots`) doesn't depend on incidental
116	      // trailing whitespace within a "blank" gap line.
117	      return { line: startLine + node.lines.length + node.trailingGap.length - 1, ch: 0 };
118	    }
119	    const lastLine = node.lines[node.lines.length - 1] ?? '';
120	    return { line: startLine + node.lines.length - 1, ch: lastLine.length };
121	  }
122	  let line = startLine + node.lines.length + node.trailingGap.length;
123	  // Preceding siblings must be skipped by their FULL subtree size — a
124	  // sibling's own lines+gap alone undercounts it if it has descendants of
125	  // its own (the bug a naive `sibling.lines.length + sibling.trailingGap.
126	  // length` sum would introduce: it silently landed inside an earlier
127	  // sibling's subtree instead of at the actual last child).
128	  for (let i = 0; i < node.children.length - 1; i++) {
129	    line += subtreeLineCount(node.children[i]!);
130	  }
131	  return subtreeCoverEnd(node.children[node.children.length - 1]!, line);
132	}
133	
134	function childrenAtScope(doc: OutlineDoc, scopePath: NodePath): readonly OutlineNode[] {
135	  let list: readonly OutlineNode[] = doc.children;
136	  for (const index of scopePath) list = list[index]!.children;
137	  return list;
138	}
139	
140	/** A contiguous line-range cover, `start` inclusive through `end` inclusive
141	 * (both `LinePos`). Exported for `select-all-ladder.ts` (progressive-
142	 * select-all), which builds its rung sequence from the same subtree-cover
143	 * geometry rather than recomputing it. */
144	export interface Cover {
145	  readonly start: LinePos;
146	  readonly end: LinePos;
147	}
148	
149	/** A node's whole-subtree cover — its own lines through its deepest last
150	 * descendant's content end, INCLUDING that leaf's own trailing gap in full
151	 * (see `subtreeCoverEnd`). Exported for `select-all-ladder.ts`. */
152	export function subtreeCoverOf(doc: OutlineDoc, node: OutlineNode): Cover {
153	  const start = startLineOf(doc, node);
154	  return { start: { line: start, ch: 0 }, end: subtreeCoverEnd(node, start) };
155	}
156	
157	/**
158	 * The minimal contiguous run of sibling subtrees (at the ends' deepest
159	 * common ancestor scope) spanning two distinct nodes, plus its combined
160	 * cover — the shared geometry both `escalateRange` (to compute the
161	 * expand-only union) and `coveredSubtreeRoots` (to test an existing range
162	 * against it) need. The cover's end includes the last subtree's own
163	 * trailing gap in full (`subtreeCoverEnd`), so reaching a node's content by
164	 * crossing into it is enough to pull its whole gap into the cover — no
165	 * separate drag onto the blank line required. See `escalateRange`'s own doc
166	 * comment for the "one node is an ancestor of the other" scope-resolution
167	 * note; unchanged here, just extracted so both callers agree by
168	 * construction rather than by duplicated logic.
169	 */
170	function siblingRunCover(
171	  doc: OutlineDoc,
172	  anchorNode: OutlineNode,
173	  headNode: OutlineNode,
174	): { readonly nodes: readonly OutlineNode[]; readonly cover: Cover } {
175	  const anchorPath = findPath(doc, anchorNode.id)!;
176	  const headPath = findPath(doc, headNode.id)!;
177	
178	  let k = 0;
179	  while (k < anchorPath.length && k < headPath.length && anchorPath[k] === headPath[k]) k++;
180	  const scopeLen = k < anchorPath.length && k < headPath.length ? k : k - 1;
181	
182	  const scopePath = anchorPath.slice(0, scopeLen);
183	  const scopeChildren = childrenAtScope(doc, scopePath);
184	  const anchorIndex = anchorPath[scopeLen]!;
185	  const headIndex = headPath[scopeLen]!;
186	  const loIndex = Math.min(anchorIndex, headIndex);
187	  const hiIndex = Math.max(anchorIndex, headIndex);
188	  const nodes = scopeChildren.slice(loIndex, hiIndex + 1);
189	  const firstSubtree = nodes[0]!;
190	  const lastSubtree = nodes[nodes.length - 1]!;
191	
192	  return {
193	    nodes,
194	    cover: {
195	      start: { line: startLineOf(doc, firstSubtree), ch: 0 },
196	      end: subtreeCoverEnd(lastSubtree, startLineOf(doc, lastSubtree)),
197	    },
198	  };
199	}
200	
201	/**
202	 * The expand-only invariant (D4 amendment): the escalated range is the
203	 * UNION of the computed cover and the original range — escalation only
204	 * ever moves ends outward, never pulls one back. Without this, an end the
205	 * user placed beyond the cover (a trailing gap line, the document's final
206	 * empty line) would be dragged back to the last content character —
207	 * concretely, Select All in a no-frontmatter note would silently drop its
208	 * trailing newline from the selection (sharpest in a single-node note,
209	 * where the head-on-final-gap-line shape is exactly the gap-line trigger).
210	 * Returns the ORIGINAL range object when the union changes nothing, so
211	 * callers can use identity/equality to detect a real escalation.
212	 */
213	function expandToCover(range: LineRange, cover: Cover): LineRange {
214	  const lo = isBackward(range) ? range.head : range.anchor;
215	  const hi = isBackward(range) ? range.anchor : range.head;
216	  const newLo = posBefore(cover.start, lo) ? cover.start : lo;
217	  const newHi = posBefore(hi, cover.end) ? cover.end : hi;
218	  if (posEqual(newLo, lo) && posEqual(newHi, hi)) return range;
219	  return isBackward(range) ? { anchor: newHi, head: newLo } : { anchor: newLo, head: newHi };
220	}
221	
222	/**
223	 * Escalate one selection range per D4 (as amended). Returns `range`
224	 * unchanged for: empty ranges (cursors — never altered), ranges with
225	 * either end in the preamble (D5 jurisdiction), and ranges whose ends both
226	 * rest on a single node's own content lines. Escalates to the node's whole
227	 * subtree when a same-node range has an end on a trailing gap line (the
228	 * single-node-selection trigger), and to the minimal contiguous run of
229	 * whole sibling subtrees when the ends resolve to different nodes — in
230	 * both cases unioned with the original range (expand-only) and with
231	 * orientation preserved.
232	 */
233	export function escalateRange(doc: OutlineDoc, range: LineRange): LineRange {
234	  if (isEmpty(range)) return range;
235	
236	  const anchorNode = nodeAtLine(doc, range.anchor.line);
237	  const headNode = nodeAtLine(doc, range.head.line);
238	  if (!anchorNode || !headNode) return range; // preamble jurisdiction (D5)
239	
240	  if (anchorNode === headNode) {
241	    // Same node: untouched while both ends stay on the node's own content
242	    // lines; an end on a trailing gap line escalates to this one node's
243	    // subtree (the drag-past-the-end-selects-the-node gesture).
244	    const start = startLineOf(doc, anchorNode);
245	    const firstGapLine = start + anchorNode.lines.length;
246	    if (range.anchor.line < firstGapLine && range.head.line < firstGapLine) return range;
247	    return expandToCover(range, subtreeCoverOf(doc, anchorNode));
248	  }
249	
250	  // Deepest common ancestor scope: the longest shared index prefix of the
251	  // two paths. When one node is an ancestor of the other (paths differ in
252	  // length with no divergence — the "selection leaves a parent" case, D4),
253	  // the scope is one level ABOVE the shallower node, so its own sibling
254	  // index is used as both endpoints' subtree index. (See `siblingRunCover`.)
255	  return expandToCover(range, siblingRunCover(doc, anchorNode, headNode).cover);
256	}
257	
258	/**
259	 * Escalate a full selection's ranges with the uniform multi-range rule (D4
260	 * amendment): every range is first escalated independently; if ANY range
261	 * escalated, every other non-empty in-jurisdiction range is then escalated
262	 * to at least its own node's whole subtree. The result is that an
263	 * escalated multi-range selection is always a set of whole-subtree ranges
264	 * — a multi-range copy concatenates complete subtrees, never a mix of
265	 * block-level and mid-node fragments. Cursors and preamble ranges are
266	 * never touched; when nothing escalates, all ranges come back unchanged.
267	 */
268	export function escalateRanges(doc: OutlineDoc, ranges: readonly LineRange[]): LineRange[] {
269	  const escalated = ranges.map((range) => escalateRange(doc, range));
270	  const anyEscalated = escalated.some((range, i) => !rangesEqual(range, ranges[i]!));
271	  if (!anyEscalated) return escalated;
272	
273	  return escalated.map((range, i) => {
274	    if (!rangesEqual(range, ranges[i]!)) return range; // already escalated
275	    if (isEmpty(range)) return range; // cursors never move (this function's own scope — see ./caret.ts's resolvePlacement for cursor placement)
276	    const anchorNode = nodeAtLine(doc, range.anchor.line);
277	    const headNode = nodeAtLine(doc, range.head.line);
278	    if (!anchorNode || !headNode) return range; // preamble jurisdiction
279	    // An unchanged non-empty in-jurisdiction range is a same-node content
280	    // range — force it up to its node's whole subtree. (expandToCover also
281	    // makes the already-exact-cover case a clean no-op.)
282	    return expandToCover(range, subtreeCoverOf(doc, anchorNode));
283	  });
284	}
285	
286	/**
287	 * The escalated-selection-decoration query (docs/research/13, "Escalated-
288	 * selection visual treatment"): does `range`'s current bounds cover a
289	 * single node's whole subtree, or the combined cover of a contiguous run of
290	 * sibling subtrees? Returns the covered subtree roots (length 1 for a
291	 * single-node cover) when so, `null` otherwise.
292	 *
293	 * The match is `lo` at the cover's exact start AND `hi` at-or-beyond the
294	 * cover's end — NOT strict equality on both ends. `cover.end` is already
